const addBookSlotButton=document.createElement('button');addBookSlotButton.id='addBookSlotBtn';addBookSlotButton.type='button';addBookSlotButton.textContent='＋ Adicionar mais';addBookSlotButton.title='Adicionar espaço de livro · até 99';
