function prepareBookSlots(){
 bookPage=Math.min(Math.max(0,bookPage),Math.floor((bookCapacity-1)/3));
 const start=bookPage*3,container=document.getElementById('roomBooks');
 const wanted=Array.from({length:Math.min(3,bookCapacity-start)},(_,i)=>start+i);
 if([...container.querySelectorAll('[data-room-book-slot]')].map(button=>Number(button.dataset.roomBookSlot)).join(',')!==wanted.join(',')){
  container.replaceChildren(...wanted.map(slot=>{const button=document.createElement('button');button.type='button';button.className='room-book-slot';button.dataset.roomBookSlot=slot;return button}));
 }
 renderBookNavigation();
}
function renderBookNavigation(){
 if(!document.getElementById('bookSlotNavigation'))return;
 bookNavStart=Math.min(Math.max(0,bookNavStart),Math.floor((bookCapacity-1)/9)*9);
 bookNavigation.replaceChildren();
 const make=(text,label,disabled,action)=>{const button=document.createElement('button');button.type='button';button.textContent=text;button.setAttribute('aria-label',label);button.disabled=disabled;button.onclick=action;bookNavigation.append(button);return button};
 make('‹','Espaços de livros anteriores',bookNavStart===0,()=>{bookNavStart-=9;bookPage=Math.floor(bookNavStart/3);renderRoomBookSlots();loadVisibleBookCovers()});
 for(let slot=bookNavStart;slot<Math.min(bookCapacity,bookNavStart+9);slot++){
  const button=make(String(slot+1),'Ir ao livro '+(slot+1),false,()=>{bookPage=Math.floor(slot/3);renderRoomBookSlots();loadVisibleBookCovers();document.querySelector(`[data-room-book-slot="${slot}"]`)?.focus()});
  button.classList.toggle('active',Math.floor(slot/3)===bookPage);button.setAttribute('aria-current',Math.floor(slot/3)===bookPage?'true':'false');
 }
 make('›','Próximos espaços de livros',bookNavStart+9>=bookCapacity,()=>{bookNavStart+=9;bookPage=Math.floor(bookNavStart/3);renderRoomBookSlots();loadVisibleBookCovers()});
 addBookSlotButton.disabled=bookCapacity>=99;addBookSlotButton.title=bookCapacity>=99?'Limite de 99 livros atingido':'Adicionar espaço de livro · até 99';
}
async function loadVisibleBookCovers(){
 const visible=roomBooks.filter(book=>Math.floor(Number(book.slot)/3)===bookPage&&!book.cover);
 await Promise.allSettled(visible.map(async book=>{try{book.cover=await bookCoverData(book);renderRoomBookSlots()}catch(error){console.warn('Não foi possível gerar a capa do PDF',error)}}));
}
