function updateBookSaveState(){
 const button=document.getElementById('saveRoomBook'),status=document.getElementById('bookCloudStatus'),book=openedRoomBook;
 if(!book)return;
 const saving=savingCloudBooks.has(book.id);
 button.disabled=!active||!bookCloudAvailable||Boolean(book.cloudSaved)||saving;
 button.textContent=saving?'SALVANDO…':book.cloudSaved?'SALVO NA NUVEM':'SALVAR';
 document.getElementById('deleteRoomBook').disabled=saving;
 status.textContent=saving?'Salvando PDF na nuvem. Aguarde a confirmação…':book.cloudSaved?'Livro salvo na nuvem até ser excluído.':!active?'Entre na mesa para salvar este livro na nuvem.':!bookCloudAvailable?'Salvamento na nuvem indisponível neste servidor.':'PDF temporário. Clique em Salvar para mantê-lo na nuvem.';
}
async function saveRoomBookToCloud(){
 const book=openedRoomBook;if(!book||book.cloudSaved||savingCloudBooks.has(book.id))return;
 if(!active){toast('Entre na mesa antes de salvar o livro.');return}
 savingCloudBooks.add(book.id);updateBookSaveState();
 const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),300000);
 try{
  const response=await fetch('/api/books/save?'+new URLSearchParams({room,id:book.id,player:uid}),{method:'POST',signal:controller.signal}),data=await readApiJson(response);
  Object.assign(book,data.book);const cached=roomBooks.find(item=>item.id===book.id);if(cached)Object.assign(cached,data.book);
  await send({type:'book-added',id:book.id,slot:book.slot});toast('Livro salvo na nuvem.');
 }catch(error){
  const message=error.name==='AbortError'?'A confirmação demorou. Reabra o livro para conferir o salvamento.':error.message||'Não foi possível salvar o livro na nuvem.';
  toast(message);if(openedRoomBook?.id===book.id)document.getElementById('bookCloudStatus').textContent=message;
 }finally{clearTimeout(timeout);savingCloudBooks.delete(book.id);if(openedRoomBook?.id===book.id){
  const status=document.getElementById('bookCloudStatus'),message=status.textContent;updateBookSaveState();if(!book.cloudSaved)status.textContent=message;
 }}
}
document.getElementById('saveRoomBook').addEventListener('click',saveRoomBookToCloud);

function updateMicrophoneGainLabel(){
 updateVoiceAutoLevelUi();
 const slider=document.getElementById('microphoneSendGain'),label=document.getElementById('microphoneSendGainValue');
 if(slider){slider.value=String(effectiveMicrophoneGain());slider.disabled=false}
 if(label)label.textContent=effectiveMicrophoneGain()+'%';
 const hint=document.getElementById('microphoneSendGainHint');
 if(hint)hint.textContent=media&&needsMicrophoneProcessing()&&!microphoneInput.track()?'Voz original: processamento antirretorno indisponível neste navegador.':media?.getAudioTracks()[0]?.getSettings?.().echoCancellation===false?'Este navegador informou cancelamento de eco desligado. Abra Verificar áudio da chamada.':echoProtection?'Antirretorno reforçado: o envio do microfone é reduzido enquanto você ouve outra voz. Pode limitar falas simultâneas.':microphoneGain===100?(voiceAutoLevel?'100% usa a voz nivelada pelo navegador, com cancelamento de eco.':'100% usa a voz sem amplificação adicional, com cancelamento de eco.'):'Volume manual do microfone. O cancelamento de eco permanece ativo; a trilha não é alterada.';
}
let microphoneGainUpdate=Promise.resolve();
function applyMicrophoneGain(){
 microphoneGainUpdate=microphoneGainUpdate.catch(()=>{}).then(async()=>{
  const stream=media;if(!stream)return;
  try{
   if(needsMicrophoneProcessing()){if(!microphoneInput.track())await microphoneInput.start(stream,effectiveMicrophoneGain()/100);else microphoneInput.setLevel(effectiveMicrophoneGain()/100);microphoneInput.setMuted(muted)}
   if(media!==stream)return;
   const track=currentAudioTrack();
   for(const pc of peers.values())for(const sender of pc.getSenders())if(sender.track?.kind==='audio'&&sender.track!==track)await sender.replaceTrack(track);
   if(!needsMicrophoneProcessing())microphoneInput.stop();
   refreshEchoReference();
  }catch{toast('Não foi possível aplicar o ganho. Reative o microfone para tentar novamente.')}
  updateMicrophoneGainLabel();
 });return microphoneGainUpdate;
}
document.getElementById('microphoneSendGain').addEventListener('input',event=>{
 microphoneGain=Math.max(0,Math.min(400,Number(event.target.value)||0));
 localStorage.setItem('mesa:microphone-gain',String(microphoneGain));
 if(media&&needsMicrophoneProcessing())microphoneInput.unlock().catch(()=>{});
 applyMicrophoneGain();updateMicrophoneGainLabel();
});
function updateEchoProtection(){
 if(echoProtection)outputVolume=Math.min(100,outputVolume);
 const checkbox=document.getElementById('echoProtection');if(checkbox)checkbox.checked=echoProtection;
 document.getElementById('cameraAudioGain').max=String(echoProtection?100:300);
 document.querySelectorAll('[data-output-volume]').forEach(slider=>{slider.max=String(echoProtection?100:300);slider.value=String(outputVolume)});
 updateRemoteAudio();updateMicrophoneGainLabel();
}
document.getElementById('echoProtection').addEventListener('change',event=>{
 echoProtection=event.target.checked;localStorage.setItem('mesa:echo-protection',echoProtection?'on':'off');
 updateEchoProtection();applyMicrophoneGain();
});
updateEchoProtection();

// Call choices are explicit on every new transmission; OS permission prompts remain browser-managed.
let callStarting=false;
function remoteVoiceTracks(id,stream){
 if(id===uid)return [];
 const ownIds=new Set((media?.getAudioTracks()||[]).map(track=>track.id));
 const processed=microphoneInput.track();if(processed)ownIds.add(processed.id);
 return (stream?.getAudioTracks?.()||[]).filter(track=>track.readyState==='live'&&!ownIds.has(track.id));
}
async function toggleMedia(){
 if(!active){toast('Entre na mesa antes de ativar a câmera e o microfone.');return}
 if(callStarting)return;
 if(media?.getVideoTracks().length){toggleCameraTrack();return}
 const dialog=document.getElementById('callStartOverlay');if(!dialog.hidden)return;
 dialog.hidden=false;document.getElementById('callStartMicrophone').checked=true;document.getElementById('callStartSound').checked=true;
 const select=document.getElementById('callMicrophoneDevice');select.replaceChildren(new Option('Microfone padrão do aparelho',''));
 document.getElementById('confirmCallStart').focus();
 try{
  const devices=await navigator.mediaDevices?.enumerateDevices();
  for(const device of devices||[])if(device.kind==='audioinput'&&device.deviceId&&device.deviceId!=='default'&&device.label)select.add(new Option(device.label,device.deviceId));
 }catch{}
}
function closeCallStart(){document.getElementById('callStartOverlay').hidden=true;document.getElementById('cameraBtn')?.focus()}
document.getElementById('cancelCallStart').addEventListener('click',closeCallStart);
document.getElementById('callStartOverlay').addEventListener('click',event=>{if(event.target.id==='callStartOverlay')closeCallStart()});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!document.getElementById('callStartOverlay').hidden)closeCallStart()});
document.getElementById('callStartForm').addEventListener('submit',event=>{
 event.preventDefault();const options={microphone:document.getElementById('callStartMicrophone').checked,sound:document.getElementById('callStartSound').checked,deviceId:document.getElementById('callMicrophoneDevice').value};
 document.getElementById('callStartOverlay').hidden=true;startMediaCall(options);
});

function updateVoiceAutoLevelUi(){
 const checkbox=document.getElementById('voiceAutoLevel'),label=document.getElementById('voiceAutoLevelState');
 if(checkbox)checkbox.checked=voiceAutoLevel;
 if(!label)return;
 const track=media?.getAudioTracks()[0],actual=track?.getSettings?.().autoGainControl;
 label.textContent=!voiceAutoLevel?'Nivelamento automático desligado; volume manual disponível.':!track?'Ajusta automaticamente vozes baixas antes do envio. Comece com o volume do microfone em 100%.':actual===true?'Nivelamento automático confirmado pelo navegador.':actual===false?'O navegador não ativou o nivelamento. Consulte Verificar áudio da chamada.':'Nivelamento solicitado; este navegador não informou o estado. Consulte o diagnóstico.';
}
let voiceLevelUpdate=Promise.resolve();
function applyVoiceAutoLevel(){
 voiceLevelUpdate=voiceLevelUpdate.catch(()=>{}).then(async()=>{
  const stream=media;if(!stream){updateVoiceAutoLevelUi();return}
  const enabled=voiceAutoLevel;
  await Promise.all(stream.getAudioTracks().map(track=>MesaVoiceAudio.protectMicrophone(track,enabled)));
  if(media!==stream)return;
  updateVoiceAutoLevelUi();updateMicrophoneGainLabel();
  if(typeof publishCallAudioStatus==='function')publishCallAudioStatus();
 });return voiceLevelUpdate;
}
document.getElementById('voiceAutoLevel').addEventListener('change',event=>{
 voiceAutoLevel=event.target.checked;localStorage.setItem('mesa:voice-auto-level',voiceAutoLevel?'on':'off');
 if(voiceAutoLevel&&microphoneGain>100){microphoneGain=100;localStorage.setItem('mesa:microphone-gain','100');applyMicrophoneGain()}
 updateVoiceAutoLevelUi();applyVoiceAutoLevel();
});
updateVoiceAutoLevelUi();
